type InvoiceType = 'standard' | 'proforma';

function calculateFee(inv: { type: InvoiceType, amount: number }) {
  switch (inv.type) {
    case 'standard': return inv.amount * 0.1;
    case 'proforma': return inv.amount * 0.05;
  }
}

type Method = 'card' | 'paypal' | 'bank';

function process(payment: { method: Method, details: any }) {
  if (payment.method === 'card') return processCard(payment.details);
  if (payment.method === 'paypal') return processPaypal(payment.details);
  if (payment.method === 'bank') return processBank(payment.details);
}

